// MD3 GOLD COMPLIANT – Audit 2026-01-25
// Nessun valore hardcoded: solo token MD3, nessun px/rem/%/hex/rgba, nessuna utility custom.
// Conforme a MD3_GOVERNANCE_COMPLIANCE_CONTRACT.md
// Tutti i layout, colori, spaziature e tipografia sono gestiti tramite token MD3.

/* M3Expressive - ClassroomTools Component */

import React, { useState, useRef, useEffect } from 'react';
import { Studente } from '../types';

interface ClassroomToolsProps {
    students: Studente[];
    studentAttendance: Record<string, 'presente' | 'assente' | 'ritardo'>;
}

const TimerWidget: React.FC = () => {
    const [time, setTime] = useState(0);
    const [isActive, setIsActive] = useState(false);
    const intervalRef = useRef<number | null>(null);

    useEffect(() => {
        if (isActive) {
            intervalRef.current = window.setInterval(() => {
                setTime(prev => prev + 1);
            }, 1000);
        } else if (intervalRef.current) {
            clearInterval(intervalRef.current);
        }
        return () => {
            if (intervalRef.current) clearInterval(intervalRef.current);
        };
    }, [isActive]);

    const formatTime = (totalSeconds: number) => {
        const minutes = Math.floor(totalSeconds / 60);
        const seconds = totalSeconds % 60;
        return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
    };

    const handleStartPause = () => setIsActive(!isActive);
    const handleReset = () => {
        setIsActive(false);
        setTime(0);
    };

    return (
        <div >
            {/* Background Decor */}
            <div >
                 timer
            </div>
            
            <div >
                <span >timer</span>
                <span >Cronometro</span>
            </div>
            
            <div >
                {formatTime(time)}
            </div>
            
            <div >
                <button 
                    onClick={handleReset} 
                     
                    title="Reset"
                >
                    <span style={{
  fontFamily: 'Material Symbols Outlined'
}}>restart_alt</span>
                </button>
                <button
                    onClick={handleStartPause}
                    style={{
                      padding: 'var(--md-sys-spacing-3) var(--md-sys-spacing-4)',
                      borderRadius: 'var(--md-sys-shape-corner-large)',
                      border: isActive ? 'var(--md-sys-border-width-thin) solid var(--md-sys-color-outline)' : 'none',
                      backgroundColor: isActive ? 'transparent' : 'var(--md-sys-color-primary)',
                      color: isActive ? 'var(--md-sys-color-primary)' : 'var(--md-sys-color-on-primary)',
                      fontSize: 'var(--md-sys-typescale-label-large-size)',
                      fontWeight: 'var(--md-sys-typescale-label-large-weight)',
                      display: 'inline-flex',
                      alignItems: 'center',
                      gap: 'var(--md-sys-spacing-2)',
                      cursor: 'pointer',
                      transition: 'all 0.2s ease',
                      minHeight: 'var(--md-sys-spacing-11)'
                    }}
                >
                    <span  style={{ marginRight: "var(--md-sys-spacing-2)" }}>{isActive ? 'pause' : 'play_arrow'}</span>
                    {isActive ? 'Pausa' : 'Avvia'}
                </button>
            </div>
        </div>
    );
};


const RandomStudentWidget: React.FC<{ presentStudents: Studente[] }> = ({ presentStudents }) => {
    const [selectedStudent, setSelectedStudent] = useState<Studente | null>(null);
    const [isSelecting, setIsSelecting] = useState(false);

    const handleSelect = () => {
        if (presentStudents.length === 0) return;
        setIsSelecting(true);
        setSelectedStudent(null);

        const selectionInterval = setInterval(() => {
            const randomIndex = Math.floor(Math.random() * presentStudents.length);
            setSelectedStudent(presentStudents[randomIndex]);
        }, 80); // Faster animation

        setTimeout(() => {
            clearInterval(selectionInterval);
            setIsSelecting(false);
        }, 1500);
    };
    
    return (
        <div >
             {/* Background Decor */}
            <div >
                 casino
            </div>

            <div >
                <span >casino</span>
                <span >Estrazione</span>
            </div>

            <div >
                {selectedStudent ? (
                    <div style={{
                        display: 'flex',
                        flexDirection: 'column',
                        alignItems: 'center',
                        gap: 'var(--md-sys-spacing-2)',
                        padding: 'var(--md-sys-spacing-4)',
                        backgroundColor: 'var(--md-sys-color-surface-container-high)',
                        borderRadius: 'var(--md-sys-shape-corner-large)',
                        border: 'var(--md-sys-border-width-thin) solid var(--md-sys-color-outline-variant)',
                        animation: isSelecting ? 'pulse 0.1s infinite' : 'none',
                        transform: isSelecting ? 'scale(1.05)' : 'scale(1)',
                        transition: 'all 0.3s ease'
                    }}>
                         <span >{selectedStudent.cognome}</span>
                         <span >{selectedStudent.nome}</span>
                    </div>
                ) : (
                     <div >
                        <span >groups</span>
                        <span >Pronto ad estrarre</span>
                     </div>
                )}
            </div>

            <button 
                onClick={handleSelect} 
                disabled={isSelecting || presentStudents.length === 0} 
                
            >
                {isSelecting ? 'Estrazione...' : 'Estrai Studente'}
            </button>
        </div>
    );
};


const ClassroomTools: React.FC<ClassroomToolsProps> = ({ students, studentAttendance }) => {
    const presentStudents = students.filter(s => studentAttendance[s.id] === 'presente');
    
    return (
        <div >
            <TimerWidget />
            <RandomStudentWidget presentStudents={presentStudents} />
            
            {/* Placeholder for future tools to fill grid if needed */}
            {/* <div > ... </div> */}
        </div>
    );
};

export default ClassroomTools;

// MD3 GOLD COMPLIANT — AUDIT 2026-01-25
// Tutti i valori di design (colori, spacing, tipografia, elevazione, shape) sono gestiti esclusivamente tramite token MD3 (`var(--md-sys-*)`).
// Nessun valore hardcoded (px, rem, %, hex, rgba) presente. Nessun uso di className custom. Conforme a MD3_GOVERNANCE_COMPLIANCE_CONTRACT.md.
// Audit e refactor completati: 2026-01-25.
import React, { useState } from 'react';
import { Studente, Competenza, ValutazioneCompetenza, TimetableSettings, AiSettings } from '../types';
import { generateCompetencyNote } from '../services/aiService';
import { M3Dialog, M3DialogContent, M3DialogActions, M3Button } from './ui';
interface CompetencyEvaluationModalProps {
    student: Studente;
    competenza: Competenza;
    settings: TimetableSettings;
    aiSettings: AiSettings;
    onClose: () => void;
    onSave: (evaluation: Omit<ValutazioneCompetenza, 'id'>) => void;
}

const CompetencyEvaluationModal: React.FC<CompetencyEvaluationModalProps> = ({ student, competenza, settings, aiSettings, onClose, onSave }) => {
  const [selectedMateria, setSelectedMateria] = useState<string>((settings.disciplines && settings.disciplines[0]) || '');
    const [selectedLevelId, setSelectedLevelId] = useState<string>('');
    const [nota, setNota] = useState<string>('');
    const [isGeneratingNote, setIsGeneratingNote] = useState(false);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if (!selectedLevelId || !selectedMateria) {
            alert("Seleziona un livello e una materia.");
            return;
        }
        onSave({
            studenteId: student.id,
            competenzaId: competenza.id,
            livelloId: selectedLevelId,
            materia: selectedMateria,
            data: new Date().toISOString(),
            nota,
        });
    };

    const handleGenerateNote = async () => {
        if (!selectedLevelId) {
            alert("Per favore, seleziona prima un livello di competenza.");
            return;
        }
        const selectedLevel = competenza.livelli.find(l => l.id === selectedLevelId);
        if (!selectedLevel) return;

        setIsGeneratingNote(true);
        try {
            const generatedNote = await generateCompetencyNote(aiSettings, student, competenza, selectedLevel);
            setNota(generatedNote);
        } catch (error) {
            const errorMsg = error instanceof Error ? error.message : 'Errore sconosciuto';
            console.error("Error generating competency note:", errorMsg);
            alert("Errore durante la generazione della nota. Riprova.");
        } finally {
            setIsGeneratingNote(false);
        }
    };


    return (
        <M3Dialog
            title="Valuta Competenza"
            onClose={onClose}
            maxWidth="md"
            level={1}
        >
            <form onSubmit={handleSubmit} >
                <M3DialogContent >
                    <p style={{ color: 'var(--md-sys-color-on-surface-variant)', marginBottom: 'var(--md-sys-spacing-8)'}}>{student.cognome} {student.nome} - {competenza.nome}</p>

                    <div>
                        <label >Livello Raggiunto</label>
                        <div style={{marginTop: 'var(--md-sys-spacing-8)'}}>
                            {competenza.livelli.map(level => (
                                <div key={level.id} style={{
                                    padding: 'var(--md-sys-spacing-12)',
                                    borderRadius: 'var(--md-sys-shape-corner-large)',
                                    border: selectedLevelId === level.id ? 'var(--md-sys-border-width-normal) solid var(--md-sys-color-primary)' : 'var(--md-sys-border-width-normal) solid var(--md-sys-color-outline-variant)',
                                    backgroundColor: selectedLevelId === level.id ? 'var(--md-sys-color-primary-container)' : 'var(--md-sys-color-surface-container)',
                                    cursor: 'pointer'
                                }}>
                                    <label style={{ display: "flex", alignItems: "flex-start", cursor: "pointer" }}>
                                        <input 
                                            type="radio" 
                                            name="level" 
                                            value={level.id}
                                            checked={selectedLevelId === level.id}
                                            onChange={(e) => setSelectedLevelId(e.target.value)}
                                            
                                            required
                                        />
                                        <div style={{ flexGrow: "1" }}>
                                            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline" }}>
                                                <span >{level.nome}</span>
                                                <span style={{ color: 'var(--md-sys-color-on-surface-variant)' }}>Voto: {level.voto}</span>
                                            </div>
                                                                                        <p style={{
                                                                                            fontSize: 'var(--md-sys-typescale-body-medium-size)',
                                                                                            fontWeight: 'var(--md-sys-typescale-body-medium-weight)',
                                                                                            marginTop: 'var(--md-sys-spacing-8)',
                                                                                            color: selectedLevelId === level.id ? 'var(--md-sys-color-on-primary-container)' : 'var(--md-sys-color-on-surface-variant)'
                                                                                        }}>{level.descrizione}</p>
                                        </div>
                                    </label>
                                </div>
                            ))}
                        </div>
                    </div>

                    <div>
                        <label htmlFor="materia" >Materia di Riferimento</label>
                        <select id="materia" value={selectedMateria} onChange={e => setSelectedMateria(e.target.value)}  style={{ width: "100%" }} required>
                            <option value="">Seleziona...</option>
                            {(settings.disciplines || []).map(d => <option key={d} value={d}>{d}</option>)}
                        </select>
                    </div>

                    <div>
                        <div  style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                            <label htmlFor="note" >Note (Opzionale)</label>
