                                {!selectedLevelId && !isGeneratingNote && (
                                    <span style={{ color: 'var(--md-sys-color-on-surface-variant)' }}>(Seleziona un livello)</span>
                                )}
                                <M3Button
                                    type="button"
                                    onClick={handleGenerateNote}
