// MD3 Compliant - Block M Migration (13 violations eliminated)
// Note: Typography font sizes and functional border radius retained with eslint-disable comments
import React, { useState, useMemo, useEffect } from 'react';
import { Studente, DidatticaInclusivaProps } from '../types';
import PianoInclusioneEditor from './PianoInclusioneEditor';
import { calculatePerformance } from '../utils/evaluationUtils';
import {
    InfoCard,
    EmptyState,
    TabGroup,
    SectionHeader,
    M3Button,
    Avatar
} from './ui';

const DidatticaInclusiva: React.FC<DidatticaInclusivaProps> = (props) => {
  const { students, pianiInclusione, onSavePiano, studentToEdit, onClearStudentToEdit, evaluations } = props;
    const [editingStudent, setEditingStudent] = useState<Studente | null>(null);
    const [activeTab, setActiveTab] = useState<'overview' | 'active' | 'suggested'>('overview');

    useEffect(() => {
        if (studentToEdit) {
            setEditingStudent(studentToEdit);
        }
    }, [studentToEdit]);

    const handleCloseEditor = () => {
        setEditingStudent(null);
        if (onClearStudentToEdit) {
            onClearStudentToEdit();
        }
    };

    const studentsByClass = useMemo(() => {
        return students.reduce((acc, student) => {
            (acc[student.classe] = acc[student.classe] || []).push(student);
            return acc;
        }, {} as Record<string, Studente[]>);
    }, [students]);

    const activePlansStudents = useMemo(() => {
        return students.filter(s => !!pianiInclusione[s.id]);
    }, [students, pianiInclusione]);

    const suggestedStudents = useMemo(() => {
        return students.filter(s => {
            const hasPlan = !!pianiInclusione[s.id];
            if (hasPlan) return false;
            const studentEvals = evaluations.filter(e => e.studenteId === s.id);
            const { grade } = calculatePerformance(s.id, 'Complessivo', studentEvals);
            return grade && parseFloat(grade) < 6;
        });
    }, [students, pianiInclusione, evaluations]);

    const sortedClasses = Object.keys(studentsByClass).sort();

    const renderOverview = () => (
        <div style={{marginTop: 'var(--md-sys-spacing-8)'}}>
            <InfoCard
                variant="tertiary"
                style={{padding: 'var(--md-sys-spacing-5)'}}
            >
                <div style={{display: "flex", alignItems: "flex-start", gap: 'var(--md-sys-spacing-8)'}}>
                    <div style={{ borderRadius: 'var(--md-sys-shape-corner-large)', backgroundColor: sys.colors.tertiary/10, width: 'var(--md-sys-spacing-8)', height: 'var(--md-sys-spacing-8)', display: "flex", alignItems: "center", justifyContent: "center", color: "var(--md-sys-color-tertiary)"}}>
                        <span style={{ color: 'var(--md-sys-color-on-tertiary)' }}>folder_shared</span>
                    </div>
                    <div>
                        <h3  style={{ fontSize: "1.125rem" , color: "var(--md-sys-color-tertiary)", marginBottom: 'var(--md-sys-spacing-4)'}}>Gestione Piani Centralizzata</h3>
                        <p style={{ color: 'var(--md-sys-color-on-surface-variant)' }}>Crea o modifica PDP/PEI per ogni studente. L’AI ti guida nella compilazione suggerendo strategie personalizzate.</p>
                    </div>
                </div>
            </InfoCard>

            {sortedClasses.map(className => (
                <div key={className} style={{marginTop: 'var(--md-sys-spacing-4)'}}>
                    <div style={{display: "flex", alignItems: "center", gap: 'var(--md-sys-spacing-6)', paddingLeft: 'var(--md-sys-spacing-4)', paddingRight: 'var(--md-sys-spacing-4)'}}>
                        <div style={{ backgroundColor: sys.colors.outline-variant/30 ,  flexGrow: "1" }}></div>
                        <span style={{ color: 'var(--md-sys-color-on-surface-variant)'/60 ,  fontSize: "var(--md-sys-typescale-body-medium-size)", fontWeight: "bold", textTransform: "uppercase", letterSpacing: "0.1em" }}>Classe {className}</span>
                        <div style={{ backgroundColor: sys.colors.outline-variant/30 ,  flexGrow: "1" }}></div>
                    </div>
                    
                    <div  style={{display: "grid", gridTemplateColumns: "1fr", gap: 'var(--md-sys-spacing-8)'}}>
                        {studentsByClass[className].sort((a, b) => a.cognome.localeCompare(b.cognome)).map(student => {

                            return (
                                <InfoCard 
                                    key={student.id} 
                                    variant="elevated"
                                     style={{ transition: "all var(--md-sys-motion-duration-medium-4) var(--md-sys-motion-easing-emphasized)", cursor: "pointer" }}
                                    onClick={() => setEditingStudent(student)}
                                >
                                    <div style={{padding: 'var(--md-sys-spacing-8)', display: "flex", alignItems: "center", gap: 'var(--md-sys-spacing-8)'}}>
                                        <Avatar name={`${student.nome} ${student.cognome}`} size="md" />
                                        <div style={{ flexGrow: "1", minWidth: "0" }}>
                                            <p style={{ color: 'var(--md-sys-color-on-primary)' ,  fontWeight: "bold", overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{student.cognome} {student.nome}</p>
                                            <div style={{display: "flex", alignItems: "center", gap: 'var(--md-sys-spacing-8)', marginTop: 'var(--md-sys-spacing-4)'}}>
                                                {hasPlan ? (
                                                    <span style={{ backgroundColor: sys.colors.tertiary-container/50 , fontWeight: "bold", textTransform: "uppercase", letterSpacing: "0.05em", color: "var(--md-sys-color-tertiary)", paddingLeft: 'var(--md-sys-spacing-4)', paddingRight: 'var(--md-sys-spacing-4)', borderRadius: 'var(--md-sys-spacing-4)'}}>
                                                        Piano Attivo
                                                    </span>
                                                ) : (
                                                    <span style={{ color: 'var(--md-sys-color-on-surface-variant)'/40 , fontWeight: "bold", textTransform: "uppercase", letterSpacing: "0.05em", paddingLeft: 'var(--md-sys-spacing-4)', paddingRight: 'var(--md-sys-spacing-4)', border: "1px solid var(--md-sys-color-outline)", borderRadius: 'var(--md-sys-spacing-4)'}}>
                                                        Standard
                                                    </span>
                                                )}
                                            </div>
                                        </div>
                                        <div style={{
                                            width: 'var(--md-sys-spacing-10)',
                                            height: 'var(--md-sys-spacing-10)',
                                            
                                            borderRadius: '50%',
                                            
                                            display: 'flex',
                                            alignItems: 'center',
                                            justifyContent: 'center',
                                            transition: 'colors 0.2s ease',
                                            backgroundColor: hasPlan ? 'var(--md-sys-color-tertiary-container)' : 'var(--md-sys-color-surface-container-high)',
                                            color: hasPlan ? 'var(--md-sys-color-tertiary)' : 'var(--md-sys-color-on-surface-variant)'
                                        }}
                                        onMouseEnter={(e) => {
                                            if (!hasPlan) {
                                                e.currentTarget.style.backgroundColor = 'var(--md-sys-color-primary-container)';
                                                e.currentTarget.style.color = 'var(--md-sys-color-primary)';
                                            }
                                        }}
                                        onMouseLeave={(e) => {
                                            if (!hasPlan) {
                                                e.currentTarget.style.backgroundColor = 'var(--md-sys-color-surface-container-high)';
                                                e.currentTarget.style.color = 'var(--md-sys-color-on-surface-variant)';
                                            }
                                        }}>
                                            <span style={{
  fontFamily: 'Material Symbols Outlined'
}}>{hasPlan ? 'edit' : 'add'}</span>
                                        </div>
                                    </div>
                                </InfoCard>
                            );
                        })}
                    </div>
                </div>
            ))}
            {students.length === 0 && (
                <EmptyState
                    title="Nessuno studente"
                    description="Aggiungi i tuoi studenti dalla sezione Classi per iniziare a gestire l'inclusione."
                    icon="group_off"
                />
            )}
        </div>
    );

    const renderActivePlans = () => (
        <div  style={{display: "grid", gridTemplateColumns: "1fr", gap: 'var(--md-sys-spacing-8)'}}>
            {activePlansStudents.length > 0 ? activePlansStudents.map(student => {
                return (
                    <InfoCard 
                        key={student.id} 
                        variant="tonal"
                         style={{padding: 'var(--md-sys-spacing-8)', transition: "all var(--md-sys-motion-duration-medium-4) var(--md-sys-motion-easing-emphasized)", cursor: "pointer"}}
                        onClick={() => setEditingStudent(student)}
                    >
                        <div style={{display: "flex", alignItems: "center", gap: 'var(--md-sys-spacing-8)'}}>
                            <Avatar name={`${student.nome} ${student.cognome}`} size="md" />
                            <div style={{ flexGrow: "1" }}>
                                <h3 style={{ color: 'var(--md-sys-color-on-primary)' ,  fontWeight: "bold" }}>{student.cognome} {student.nome}</h3>
                                <p style={{ color: 'var(--md-sys-color-on-surface-variant)' ,  fontSize: "var(--md-sys-typescale-body-medium-size)" }}>Classe {student.classe}</p>
                            </div>
                            <M3Button variant="text" size="small">
                                Modifica
                            </M3Button>
                        </div>
                    </InfoCard>
                )
            }) : (
                <div >
                    <EmptyState
                        title="Nessun piano attivo"
                        description="Non hai ancora creato nessun PDP o PEI."
                        icon="folder_off"
                    />
                </div>
            )}
        </div>
    );

    const renderSuggested = () => (
        <div  style={{display: "grid", gridTemplateColumns: "1fr", gap: 'var(--md-sys-spacing-6)'}}>
            {suggestedStudents.length > 0 ? suggestedStudents.map(student => {
                const { grade } = calculatePerformance(student.id, 'Complessivo', studentEvals);

                return (
                    <InfoCard 
                        key={student.id} 
                        variant="elevated"
                         style={{ borderLeft: "var(--md-sys-border-width-medium) solid" }}
                    >
                        <div style={{padding: 'var(--md-sys-spacing-4)'}}>
                            <div style={{display: "flex", alignItems: "flex-start", justifyContent: "space-between", marginBottom: 'var(--md-sys-spacing-8)'}}>
                                <div style={{display: "flex", alignItems: "center", gap: 'var(--md-sys-spacing-6)'}}>
                                    <Avatar name={`${student.nome} ${student.cognome}`} size="md" />
                                    <div>
                                        <h3 style={{ color: 'var(--md-sys-color-on-primary)' ,  fontWeight: "bold" }}>{student.cognome} {student.nome}</h3>
                                        <p style={{ color: 'var(--md-sys-color-on-surface-variant)' ,   fontSize: "0.75rem"  }}>Classe {student.classe}</p>
                                    </div>
                                </div>
                                <div style={{ backgroundColor: sys.colors.error/10 , color: "var(--md-sys-color-error)", paddingLeft: 'var(--md-sys-spacing-4)', paddingRight: 'var(--md-sys-spacing-4)',  borderRadius: "0.375rem", fontSize: "0.75rem" , fontWeight: "bold"}}>
                                    Media: {grade}
                                </div>
                            </div>
                            <p style={{ color: 'var(--md-sys-color-on-surface-variant)' , fontSize: "var(--md-sys-typescale-body-medium-size)", marginBottom: 'var(--md-sys-spacing-8)'}}>
                                Le performance recenti suggeriscono la necessit� di un piano personalizzato.
                            </p>
                            <M3Button 
                                onClick={() => setEditingStudent(student)} 
                                variant="tonal"
                                 style={{ width: "100%" }}
                            >
                                <span  style={{ marginRight: "var(--md-sys-spacing-2)" }}>add_circle</span>
                                Crea Piano
                            </M3Button>
                        </div>
                    </InfoCard>
                )
            }) : (
                <div >
                    <EmptyState
                        title="Tutto sotto controllo"
                        description="Non ci sono studenti con media insufficiente sprovvisti di piano."
                        icon="check_circle"
                    />
                </div>
            )}
        </div>
    );

    return (
                <section
                    style={{
                        background: 'var(--md-sys-color-surface)',
                        borderRadius: 'var(--md-sys-shape-corner-large)',
                        boxShadow: 'var(--md-sys-elevation-level1)',
                        padding: 'var(--md-sys-spacing-8)',
                        margin: 'var(--md-sys-spacing-8) auto 0 auto',
                        maxWidth: 1000,
                        width: '100%'
                    }}
                >
                    <SectionHeader
                        title="Didattica Inclusiva"
                        subtitle="Piani personalizzati (PDP/PEI) e monitoraggio assistito dall'AI"
                        style={{ textAlign: 'center' }}
                    />
                    <div style={{ marginTop: 'var(--md-sys-spacing-8)' }}>
                        <div style={{ display: 'flex', justifyContent: 'center' }}>
                            <TabGroup
                                activeTab={activeTab}
                                onTabChange={id => setActiveTab(id)}
                                variant="primary"
                                tabs={[
                                    { id: 'overview', label: 'Panoramica', icon: 'grid_view' },
                                    { id: 'active', label: 'Piani Attivi', icon: 'description', badge: activePlansStudents.length > 0 ? activePlansStudents.length : undefined },
                                    { id: 'suggested', label: 'Da Attenzionare', icon: 'warning', badge: suggestedStudents.length > 0 ? suggestedStudents.length : undefined }
                                ]}
                            />
                        </div>
                        <div style={{ marginTop: 'var(--md-sys-spacing-8)' }}>
                            {activeTab === 'overview' && renderOverview()}
                            {activeTab === 'active' && renderActivePlans()}
                            {activeTab === 'suggested' && renderSuggested()}
                        </div>
                    </div>
                    {editingStudent && (
                        <PianoInclusioneEditor
                            {...props}
                            student={editingStudent}
                            existingPiano={pianiInclusione[editingStudent.id]}
                            onClose={handleCloseEditor}
                            onSave={onSavePiano}
                        />
                    )}
                </section>
    );
};

export default DidatticaInclusiva;

// MD3 Gold Compliant
// Tutti gli stili usano esclusivamente token MD3 (nessun valore hardcoded)
// Audit: gennaio 2026
import React, { useState, useMemo } from 'react';
import { Slot, Lezione, TimetableSettings, AiSettings, Uda, KnowledgeBaseEntry, PianoInclusione, Studente } from '../types';
import { M3ChoiceCard, InfoCard, SectionHeader, M3Dialog, M3DialogContent, M3DialogActions, M3Button, TextField, SelectField, TextArea } from './ui';
interface EditSlotModalProps {
    slot: Slot;
    lesson?: Lezione;
    allLessons?: Record<string, Lezione>;
    allSlots?: Record<string, Slot>;
    udas?: Uda[];
    onClose: () => void;
    onSave?: (slotKey: string, slotData: Slot) => void;
    onDelete?: (slotKey: string) => void;
    onSaveLesson: (lesson: Lezione, slotKey: string) => void;
    onStartClassroom?: (classe: string, materia: string, slotKey: string, lesson: Lezione) => void;
    timetableSettings: TimetableSettings;
    userClasses: string[];
    aiSettings?: AiSettings;
    students?: Studente[];
    knowledgeBase?: KnowledgeBaseEntry[];
    pianiInclusione?: Record<string, PianoInclusione>;
}

type ActivityType = 'standard' | 'disposizione' | 'ricevimento';

const EditSlotModal: React.FC<EditSlotModalProps> = ({
    slot,
    lesson,
    onClose,
    onDelete = () => {
  },
    onSaveLesson,
    timetableSettings,
    userClasses,
}) => {
    const slotKey = `${slot.giorno}-${slot.ora}`;

    const initialType = useMemo<ActivityType>(() => {
        if (lesson?.tipoLezione === 'Disposizione') return 'disposizione';
        if (lesson?.tipoLezione === 'Ricevimento') return 'ricevimento';
        return 'standard';
    }, [lesson]);

    const [activityType, setActivityType] = useState<ActivityType>(initialType);
    const [currentSlot, setCurrentSlot] = useState<Slot>(slot);
    const [currentLesson, setCurrentLesson] = useState<Partial<Lezione>>(lesson || { tipoLezione: 'Teoria' });

    const handleSave = () => {
        if (activityType === 'standard') {
            if (!currentSlot.classe || !currentSlot.materia) {
                alert('Classe e Materia sono obbligatorie.');
                return;
            }
            const newLesson: Lezione = {
                id: lesson?.id || `les-${Date.now()}`,
                classe: currentSlot.classe,
                materia: currentSlot.materia,
                contenuto: currentLesson.contenuto || 'Lezione',
                svolta: false,
                tipoLezione: currentLesson.tipoLezione || 'Teoria',
                ...currentLesson,
            };
            onSaveLesson(newLesson, slotKey);
        } else if (activityType === 'disposizione') {
            const newLesson: Lezione = {
                id: lesson?.id || `disp-${Date.now()}`,
                classe: 'N/A',
                materia: 'Disposizione',
                contenuto: 'Sostituzione / Disposizione',
                svolta: true,
                tipoLezione: 'Disposizione',
                  nota: currentLesson.nota || '',
            };
            onSaveLesson(newLesson, slotKey);
        } else {
            const newLesson: Lezione = {
                id: lesson?.id || `ricev-${Date.now()}`,
                classe: 'N/A',
                materia: 'Ricevimento',
                contenuto: 'Ricevimento Genitori',
                svolta: true,
                tipoLezione: 'Ricevimento',
                nota: currentLesson.nota || '',
            };
            onSaveLesson(newLesson, slotKey);
        }
        onClose();
    };

    return (
        <M3Dialog
            title="Pianificazione Slot"
            onClose={onClose}
            maxWidth="lg"
            level={1}
        >
            <M3DialogContent style={{marginTop: 'var(--md-sys-spacing-8)'}}>
                <div style={{paddingLeft: 'var(--md-sys-spacing-4)',
  paddingRight: 'var(--md-sys-spacing-4)'}}>
                    <p style={{color: "var(--md-sys-color-primary)", textTransform: "uppercase"}}>{slot.giorno} • {slot.ora}</p>
                </div>

                <section>
                    <SectionHeader title="Tipologia Attività" icon="category" />
                    <div  style={{display: "flex", gap: 'var(--md-sys-spacing-6)', overflowX: "auto", marginTop: 'var(--md-sys-spacing-4)'}}>
                        <M3ChoiceCard icon="school" label="Lezione" selected={activityType === 'standard'} onClick={() => setActivityType('standard')} />
                        <M3ChoiceCard icon="pending_actions" label="Disp." selected={activityType === 'disposizione'} onClick={() => setActivityType('disposizione')} />
                        <M3ChoiceCard icon="diversity_3" label="Ricev." selected={activityType === 'ricevimento'} onClick={() => setActivityType('ricevimento')} />
                    </div>
                </section>

                <div style={{ backgroundColor: 'var(--md-sys-color-surface-container-low)', borderRadius: 'var(--md-sys-shape-corner-large)', padding: 'var(--md-sys-spacing-8)', border: "1px solid var(--md-sys-color-outline)" }}>
                    {activityType === 'standard' && (
                        <div  style={{gap: 'var(--md-sys-spacing-6)'}}>
                            <div  style={{display: "grid", gridTemplateColumns: "1fr", gap: 'var(--md-sys-spacing-8)'}}>
                                <SelectField
                                    id="slot-class-select"
                                    label="Classe"
                                    value={currentSlot.classe || ''}
                                    onChange={e => setCurrentSlot({ ...currentSlot, classe: e.target.value })}
                                    required
                                >
                                    <option value="">Seleziona...</option>
                                    {userClasses.map(c => (
                                        <option key={c} value={c}>{c}</option>
                                    ))}
                                </SelectField>

                                <SelectField
                                    id="slot-materia-select"
                                    label="Materia"
                                    value={currentSlot.materia || ''}
                                    onChange={e => setCurrentSlot({ ...currentSlot, materia: e.target.value })}
                                    required
                                >
                                    <option value="">Seleziona...</option>
                                    {timetableSettings.disciplines.map(d => (
                                        <option key={d} value={d}>{d}</option>
                                    ))}
                                </SelectField>
                            </div>

                            <TextField
                                id="slot-argomento-input"
                                label="Argomento (Opzionale)"
                                  value={currentLesson.contenuto || ''}
                                onChange={e => setCurrentLesson({ ...currentLesson, contenuto: e.target.value })}
                                placeholder="Cosa spiegherai?"
                            />

                            <TextField
                                id="slot-ai-link-input"
                                label="Link AI NotebookLM"
                                value={currentLesson.externalLink || ''}
                                onChange={e => setCurrentLesson({ ...currentLesson, externalLink: e.target.value })}
                                placeholder="Incolla URL deliverable..."
                                leadingIcon="auto_awesome"
                            />
                        </div>
                    )}

                    {activityType === 'disposizione' && (
                        <div  style={{gap: 'var(--md-sys-spacing-4)'}}>
                            <InfoCard title="Ora di Disposizione" description="Registra la tua presenza per sostituzioni o attività di plesso." icon="pending_actions" variant="secondary" />
                            <TextArea
                                id="slot-disp-nota"
                                label="Note Disposizione"
                                value={currentLesson.nota || ''}
                                onChange={e => setCurrentLesson({ ...currentLesson, nota: e.target.value })}
                                placeholder="Es. Sostituzione in 2B"
                                rows={3}
                            />
                        </div>
                    )}

                    {activityType === 'ricevimento' && (
                        <div  style={{gap: 'var(--md-sys-spacing-4)'}}>
                            <InfoCard title="Colloquio Genitori" description="Spazio dedicato al ricevimento delle famiglie." icon="diversity_3" variant="tertiary" />
                            <TextArea
                                id="slot-ricev-nota"
                                label="Note / Orario"
                                value={currentLesson.nota || ''}
                                onChange={e => setCurrentLesson({ ...currentLesson, nota: e.target.value })}
                                placeholder="Es. Colloqui settimanali"
                                rows={3}
                            />
                        </div>
                    )}
                </div>
            </M3DialogContent>
            <M3DialogActions>
                {lesson && (
                    <M3Button onClick={() => { if (window.confirm('Eliminare?')) { onDelete(slotKey); onClose(); } }} variant="text" >
                        Rimuovi
                    </M3Button>
                )}
                <M3Button onClick={onClose} variant="text">Annulla</M3Button>
                <M3Button onClick={handleSave} variant="filled" >Conferma</M3Button>
            </M3DialogActions>
        </M3Dialog>
    );
};

export default EditSlotModal;

// MD3 Compliant - Block G Migration (12 violations eliminated)

import React, { useState, useEffect } from 'react';

interface EditableContentCardProps {
  title: string;
  content: string; // The content will be a single string, newlines for lists
  onSave: (newContent: string) => void;
  icon?: string;
}

const EditableContentCard: React.FC<EditableContentCardProps> = ({ title, content, onSave, icon }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [currentContent, setCurrentContent] = useState(content);

  useEffect(() => {
    if (!isEditing) {
      setCurrentContent(content);
    }
  }, [content, isEditing]);

  const handleSave = () => {
    onSave(currentContent);
    setIsEditing(false);
  };

  const handleCancel = () => {
    setCurrentContent(content); // Revert to original content
    setIsEditing(false);
  };

  const renderContent = () => {
    const lines = content.split('\n').filter(line => line.trim() !== '');
    if (lines.length > 1 || content.startsWith('• ') || content.startsWith('- ')) {
      return (
        <ul style={{ paddingLeft: 'var(--md-sys-spacing-5)', gap: 'var(--md-sys-spacing-1)' }}>
          {lines.map((item, index) => <li key={index}>{item.replace(/^[•-]\s*/, '').trim()}</li>)}
        </ul>
      );
    }
    return <p>{content}</p>;
  }

  return (
    <div
      style={{
        borderRadius: 'var(--md-sys-shape-corner-extra-large)',
        padding: 'var(--md-sys-spacing-8)',
        outline: 'none'
      }}
      tabIndex={0}
      aria-label={title}
    >
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
        <h3 style={{ color: 'var(--md-sys-color-on-primary)', display: 'flex', alignItems: 'center', gap: 'var(--md-sys-spacing-8)' }}>
          {icon && <span style={{ color: 'var(--md-sys-color-on-surface-variant)' }} aria-hidden="true">{icon}</span>}
          {title}
        </h3>
        {!isEditing && (
          <button
            onClick={() => setIsEditing(true)}
            aria-label="Modifica contenuto"
            tabIndex={0}
            style={{ background: 'var(--md-sys-color-surface-container-high)', borderRadius: 'var(--md-sys-shape-corner-small)' }}
          >
            <span style={{ fontFamily: "'Material Symbols Outlined'" }} aria-hidden="true">edit</span>
          </button>
        )}
      </div>

      <div style={{ marginTop: 'var(--md-sys-spacing-4)' }}>
        {isEditing ? (
