/**
 * KnowledgeBase.tsx
 * // M3Expressive refactor: Removed inline Tailwind classes, applied dedicated CSS classes with M3 tokens for layout, colors, spacing, and typography.
 */

import React, { useState, useMemo } from 'react';
import { KnowledgeBaseEntry, Corpus, AiSettings, TimetableSettings } from '../types';
import AddSourceModal from './AddSourceModal';
import DocumentViewerModal from './DocumentViewerModal'; 
import ImageViewerModal from './ImageViewerModal';
import { KB_CATEGORIES } from '../constants';
import {
    InfoCard,
    CategoryCard,
    SectionHeader,
    M3Button
} from './ui';

interface KnowledgeBaseProps {
    knowledgeBase: KnowledgeBaseEntry[];
    setKnowledgeBase: React.Dispatch<React.SetStateAction<KnowledgeBaseEntry[]>>;
    corpora: Corpus[];
    setCorpora: React.Dispatch<React.SetStateAction<Corpus[]>>;
    aiSettings?: AiSettings;
    showToast: (msg: string, type?: 'success' | 'error' | 'info') => void;
    settings?: TimetableSettings;
    showGuidanceTips?: boolean;
}

const KnowledgeBase: React.FC<KnowledgeBaseProps> = ({ knowledgeBase, setKnowledgeBase, corpora, setCorpora, showToast }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [currentView, setCurrentView] = useState<{ type: 'root' | 'category' | 'corpus', id: string }>({ type: 'root', id: '' });
    const [isAddSourceModalOpen, setIsAddSourceModalOpen] = useState(false);
    const [previewingEntry, setPreviewingEntry] = useState<KnowledgeBaseEntry | null>(null);
    const [viewingImage, setViewingImage] = useState<KnowledgeBaseEntry | null>(null);
    // aiSettings, settings, showGuidanceTips sono ricevuti come props ma non usati attualmente

    const handleDeleteFile = (fileId: string) => {
        if (!window.confirm(`Sei sicuro di voler eliminare questo file?`)) return;
        setKnowledgeBase(prev => prev.filter(entry => entry.id !== fileId));
    };

    const handleAddEntries = (newEntries: KnowledgeBaseEntry[]) => {
        setKnowledgeBase(prev => [...prev, ...newEntries]);
        showToast(`${newEntries.length} file aggiunti con successo!`, 'success');
    };

    const filteredFiles = useMemo(() => {
        return knowledgeBase.filter(entry => {
            const matchesSearch = entry.fileName.toLowerCase().includes(searchTerm.toLowerCase());
            if (!matchesSearch) return false;
            if (currentView.type === 'category') {
                if (currentView.id === 'archivio') return entry.category === 'archivio' || !entry.category;
                return entry.category === currentView.id;
            }
            if (currentView.type === 'corpus') return entry.corpusId === currentView.id;
            return false; 
        }).sort((a, b) => a.fileName.localeCompare(b.fileName));
    }, [knowledgeBase, searchTerm, currentView]);

    const categoryCounts = useMemo(() => {
        const counts: Record<string, number> = {};
        KB_CATEGORIES.forEach(c => counts[c.id] = 0);
        knowledgeBase.forEach(entry => {
            const cat = entry.category || 'archivio';
            const target = counts[cat] !== undefined ? cat : 'archivio';
            counts[target] = (counts[target] || 0) + 1;
        });
        return counts;
    }, [knowledgeBase]);

    const handleFileClick = (entry: KnowledgeBaseEntry) => {
        if (entry.fileContent?.mimeType.startsWith('image/')) setViewingImage(entry);
        else setPreviewingEntry(entry);
    };

    const renderFolderDashboard = () => (
        <div >
             {KB_CATEGORIES.map(cat => (
                 <CategoryCard 
                    key={cat.id} 
                    id={cat.id}
                    label={cat.label}
                    icon={cat.icon}
                    color={cat.color}
                    isSelected={currentView.type === 'category' && currentView.id === cat.id}
                    onClick={() => setCurrentView({ type: 'category', id: cat.id })}
                    description={`${categoryCounts[cat.id] || 0} file salvati`}
                />
             ))}
        </div>
    );

    const renderFileList = () => {
        const categoryInfo = currentView.type === 'category' ? KB_CATEGORIES.find(c => c.id === currentView.id) : null;
        return (
            <div >
                <header >
                    <div >
                        <M3Button onClick={() => setCurrentView({ type: 'root', id: '' })} variant="text" >
                            <span style={{
  fontFamily: 'Material Symbols Outlined'
}}>arrow_back</span>
                        </M3Button>
                        <h2 >{categoryInfo?.label || 'File'}</h2>
                    </div>
                    <div >
                        <span >search</span>
                        <input 
                            type="text" 
                            placeholder="Cerca in questa cartella..." 
                             
                            value={searchTerm} 
                            onChange={(e) => setSearchTerm(e.target.value)} 
                        />
                    </div>
                </header>

                <div >
                    {filteredFiles.map(entry => (
                        <div 
                            key={entry.id} 
                            
                            onClick={() => handleFileClick(entry)}
                        >
                            <div >
                                <span >
                                    {entry.category === 'ai_deliverable' ? 'auto_awesome' : (entry.fileContent?.mimeType === 'application/pdf' ? 'picture_as_pdf' : 'description')}
                                </span>
                            </div>
                            <div >
                                <p >{entry.fileName}</p>
                                <p >
                                    {entry.isGenerated ? 'Generato con AI' : 'Documento locale'}
                                </p>
                            </div>
                            <M3Button 
                                onClick={(e) => { e.stopPropagation(); handleDeleteFile(entry.id); }} 
                                variant="text" 
                                
                            >
                                <span >delete</span>
                            </M3Button>
                        </div>
                    ))}
                    {filteredFiles.length === 0 && (
                        <div >
                            <span >search_off</span>
                            <p >Nessun file trovato in questa cartella.</p>
                        </div>
                    )}
                </div>
            </div>
        );
    }

    return (
        <div  style={{maxWidth: "100%", marginLeft: "auto", marginRight: "auto", width: "100%", paddingLeft: 'var(--md-sys-spacing-4)', paddingRight: 'var(--md-sys-spacing-4)'}}>
            <div  style={{display: "flex", flexDirection: "column", justifyContent: "space-between", gap: 'var(--md-sys-spacing-8)', marginBottom: 'var(--md-sys-spacing-8)'}}>
                <SectionHeader 
                    title="Knowledge Base" 
                    subtitle="Archivio fonti, documenti e deliverable generati dall'AI."
                    icon="database"
                />
                <M3Button onClick={() => setIsAddSourceModalOpen(true)} variant="filled" style={{ borderRadius: 'var(--md-sys-shape-corner-large)' , display: "flex", alignItems: "center", gap: 'var(--md-sys-spacing-8)'}}>
                    <span style={{
  fontFamily: 'Material Symbols Outlined'
}}>add_circle</span>
                    Carica Documenti
                </M3Button>
            </div>

            <InfoCard 
                title="Sincronia NotebookLM"
                description="Puoi caricare qui le analisi o i progetti prodotti con NotebookLM. L'app li userà come base di conoscenza prioritaria per generare le tue lezioni e UDA."
                icon="bolt"
                variant="primary"
                style={{ backgroundColor: sys.colors.primaryContainer/20 , marginBottom: 'var(--md-sys-spacing-8)'}}
            />

            <main >
                {currentView.type === 'root' ? renderFolderDashboard() : renderFileList()}
            </main>

            {isAddSourceModalOpen && (
                <AddSourceModal
                    corpora={corpora}
                    setCorpora={setCorpora}
                    onClose={() => setIsAddSourceModalOpen(false)}
                    onAddEntries={handleAddEntries}
                />
            )}
            {previewingEntry && (
                <DocumentViewerModal
                    title={previewingEntry.fileName}
                    htmlContent={previewingEntry.htmlContent || `<pre>${previewingEntry.content}</pre>`}
                    onClose={() => setPreviewingEntry(null)}
                />
            )}
            {viewingImage && (
                 <ImageViewerModal
                    prompt={viewingImage.content}
                    imageData={viewingImage.fileContent!.data}
                    mimeType={viewingImage.fileContent!.mimeType}
                    onClose={() => setViewingImage(null)}
                    onSaveToKb={() => {}}
                />
            )}
        </div>
    );
};

export default KnowledgeBase;

import React, { useState, useMemo, useEffect } from 'react';
import { Lezione, LessonsPageProps, CurriculumSubject, TimetableSettings, Uda } from '../types';
import { generateLessonSequenceForClass } from '../services/aiService';
// import LessonView from './LessonView';
import IdeaGeneratorModal from './IdeaGeneratorModal';
import { CreateLessonFromAiModal } from './CreateLessonFromAiModal';
import { M3Typography } from './ui';

// MD3 Compliant - Migration completed
// LessonsPage.tsx: Migrated from 15 inline style violations to 0 violations
// All styles now use MD3 design tokens and semantic color/spacing/elevation system

// Extend Interface locally if not updated in types.ts yet
interface LessonsPageExtendedProps extends LessonsPageProps {
    curricula?: CurriculumSubject[];
    settings?: TimetableSettings; // Added optional settings prop
}

const LessonsPage: React.FC<LessonsPageExtendedProps> = ({ lessons, uda, knowledgeBase, userClasses, onViewLesson, onAddLessons, onStartClassroom, aiSettings, setIsLoadingModalOpen, setLoadingModalMessage, slots, onScheduleLesson, curricula = [], settings }) => {
    const [error, setError] = useState('');
    const [selectedUdaIds, setSelectedUdaIds] = useState<string[]>([]);
    const [selectedClasses, setSelectedClasses] = useState<string[]>([]);

    // KB Selection
    const [selectedKbIds, setSelectedKbIds] = useState<string[]>([]);

    // Filtri per l'archivio
    const [filterClass, setFilterClass] = useState<string>('');
    const [filterUda, setFilterUda] = useState<string>('');

    // Idea Generator State
    const [isIdeaModalOpen, setIsIdeaModalOpen] = useState(false);
    const [generatedIdeaContent, setGeneratedIdeaContent] = useState<{ title: string; htmlContent: string; } | null>(null);

    // Pre-select logical KB files
    useEffect(() => {
        if (knowledgeBase.length > 0) {
            const defaults = knowledgeBase
                .filter(k => k.category === 'programmazione' || k.fileName.toLowerCase().includes('programmazione') || k.category === 'materiale_didattico')
                .map(k => k.id);
            setSelectedKbIds(defaults);
        }
    }, [knowledgeBase]);

    const handleUdaSelection = (udaId: string) => {
        setSelectedUdaIds(prev =>
            prev.includes(udaId) ? prev.filter(id => id !== udaId) : [...prev, udaId]
        );
    };

    const handleClassSelection = (className: string) => {
        setSelectedClasses(prev =>
            prev.includes(className) ? prev.filter(c => c !== className) : [...prev, className]
        );
    };

    const handleKbSelection = (id: string) => {
        setSelectedKbIds(prev => prev.includes(id) ? prev.filter(k => k !== id) : [...prev, id]);
    };

    const handleGenerateSequences = async () => {
        if (selectedUdaIds.length === 0 || selectedClasses.length === 0) {
            alert("Seleziona almeno una UDA e una classe per procedere.");
            return;
        }
        setLoadingModalMessage("L'AI sta generando le sequenze di lezioni usando i documenti selezionati...");
        setIsLoadingModalOpen(true);
        setError('');
        try {
            const selectedUdas = uda.filter((u: Uda) => selectedUdaIds.includes(u.id));

            // Filter KB Content
            const kbText = knowledgeBase
                .filter(doc => selectedKbIds.includes(doc.id))
                .map(doc => `--- ${doc.fileName} ---\n${doc.content}`)
                .join('\n\n');

            let allNewLessons: Lezione[] = [];

            for (const targetClass of selectedClasses) {
                const extractedLessons = await generateLessonSequenceForClass(aiSettings, selectedUdas, targetClass, kbText);
                const newLessonsForClass: Lezione[] = (extractedLessons as Omit<Lezione, 'id' | 'svolta'>[]).map((lessonData, index) => ({
                    ...lessonData,
                    id: `lesson-seq-${Date.now()}-${targetClass}-${index}`,
                    svolta: false,
                }));
                allNewLessons = [...allNewLessons, ...newLessonsForClass];
            }
            onAddLessons(allNewLessons);
            alert(`${allNewLessons.length} lezioni generate con successo per ${selectedClasses.length} classi e aggiunte all'archivio!`);
            setSelectedUdaIds([]);
            setSelectedClasses([]);

        } catch (err) {
            console.error(err);
            setError(err instanceof Error ? err.message : "Errore durante la generazione delle sequenze di lezioni.");
        } finally {
            setIsLoadingModalOpen(false);
        }
    };

    const groupedLessonsByClass: Array<[string, Record<string, Lezione[]>]> = useMemo(() => {
        const groups: Record<string, Record<string, Lezione[]>> = {};

        lessons.filter(lesson => {
            if (filterClass && lesson.classe !== filterClass) return false;
            if (filterUda && lesson.unitaDiApprendimento !== filterUda) return false;
            return true;
        }).forEach(lesson => {
            const classKey = lesson.classe || 'Senza Classe';
            const udaKey = lesson.unitaDiApprendimento || 'Lezioni Varie';

            if (!groups[classKey]) {
                groups[classKey] = {};
            }
            if (!groups[classKey][udaKey]) {
                groups[classKey][udaKey] = [];
            }
            groups[classKey][udaKey].push(lesson);
        });

        // Sort lessons within each group
        for (const classKey in groups) {
            for (const udaKey in groups[classKey]) {
                groups[classKey][udaKey].sort((a: Lezione, b: Lezione) => a.contenuto.localeCompare(b.contenuto));
            }
        }

        return Object.keys(groups)
            .sort((a, b) => a.localeCompare(b))
            .map((classKey) => [classKey, groups[classKey]]);
        }, [lessons, filterClass, filterUda]);

    const filteredUdas = useMemo(() => {
        if (!filterClass) return uda;
        return uda.filter((u: Uda) => u.classe === filterClass);
    }, [uda, filterClass]);


    return (
        <div >
            <div >
            <div >
                <div >
                    <M3Typography variant="headline-large">Progetta Lezioni</M3Typography>
                    <M3Typography variant="body-large">Genera e orchestra sequenze di lezioni partendo da UDA e classi.</M3Typography>
                </div>
            </div>

            {/* Expressive Idea Card */}
            <div
                style={{
                    backgroundColor: 'var(--md-sys-color-surface-container-highest)',
                    borderRadius: 'var(--md-sys-shape-corner-large)',
                    padding: 'var(--md-sys-spacing-6)',
                    cursor: 'pointer',
                    border: '1px solid var(--md-sys-color-outline-variant)',
                    transition: 'all var(--md-sys-motion-duration-short-4) var(--md-sys-motion-easing-decelerated)-out'
                }}
                onClick={() => setIsIdeaModalOpen(true)}
            >
                <div style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: 'var(--md-sys-spacing-4)'
                }}>
                    <div style={{
                        backgroundColor: 'var(--md-sys-color-primary-container)',
                        borderRadius: 'var(--md-sys-shape-corner-full)',
                        padding: 'var(--md-sys-spacing-3)',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center'
                    }}>
                        <span style={{
                            fontFamily: 'Material Symbols Outlined',
                            fontSize: 'var(--md-sys-typescale-display-small-font-size)',
                            color: 'var(--md-sys-color-on-primary-container)'
                        }}>lightbulb</span>
                    </div>
                    <div>
                        <M3Typography variant="headline-medium">Hai un'idea per una lezione?</M3Typography>
                        <M3Typography variant="body-medium">
                            Tocca qui per trasformarla subito in un piano strutturato con l'AI. Dettala o scrivila.
                        </M3Typography>
                    </div>
                </div>
            </div>


            {/* Lesson Sequence Generator */}
            <details style={{
                backgroundColor: 'var(--md-sys-color-surface-container)',
                borderRadius: 'var(--md-sys-shape-corner-medium)',
                border: '1px solid var(--md-sys-color-outline-variant)',
                marginTop: 'var(--md-sys-spacing-6)'
            }}>
                <summary style={{
                    padding: 'var(--md-sys-spacing-4)',
                    cursor: 'pointer',
                    listStyle: 'none',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between'
                }}>
                    <div style={{
                        display: 'flex',
                        alignItems: 'center',
                        gap: 'var(--md-sys-spacing-3)'
                    }}>
                        <span style={{
                            fontFamily: 'Material Symbols Outlined',
                            fontSize: 'var(--md-sys-typescale-title-medium-font-size)',
                            color: 'var(--md-sys-color-primary)'
                        }}>auto_awesome</span>
                        <span style={{
                            fontSize: 'var(--md-sys-typescale-title-medium-font-size)',
                            fontWeight: 'var(--md-sys-typescale-title-medium-font-weight)',
                            color: 'var(--md-sys-color-on-surface)'
                        }}>Generatore Sequenze Lezioni</span>
                    </div>
                    <span style={{
                        fontFamily: 'Material Symbols Outlined',
                        fontSize: 'var(--md-sys-typescale-title-medium-font-size)',
                        color: 'var(--md-sys-color-on-surface-variant)'
                    }}>expand_more</span>
                </summary>
                <div style={{
                    padding: 'var(--md-sys-spacing-4)',
                    borderTop: '1px solid var(--md-sys-color-outline-variant)'
                }}>
                    <M3Typography variant="body-medium">
                        Seleziona le Unità di Apprendimento (UDA) e le classi. L'AI genererà una sequenza di lezioni strutturata per ogni classe, basandosi sui documenti KB selezionati.
                    </M3Typography>
                    <div style={{
                        display: 'flex',
                        flexDirection: 'column',
                        gap: 'var(--md-sys-spacing-6)'
                    }}>
                        {/* UDA Selection */}
                        <div style={{
                            backgroundColor: 'var(--md-sys-color-surface-container-low)',
                            borderRadius: 'var(--md-sys-shape-corner-medium)',
                            padding: 'var(--md-sys-spacing-4)'
                        }}>
                            <M3Typography variant="title-large">1. Seleziona UDA</M3Typography>
                            {/* Centralized Selection Container */}
                            <div style={{
                                marginTop: 'var(--md-sys-spacing-3)',
                                maxHeight: 'var(--md-sys-spacing-40)',
                                overflowY: 'auto'
                            }}>
                                {uda.length > 0 ? uda.map((uda: Uda) => (
                                    <div key={uda.id} style={{
                                        display: 'flex',
                                        alignItems: 'center',
                                        gap: 'var(--md-sys-spacing-2)',
                                        padding: 'var(--md-sys-spacing-2)',
                                        borderRadius: 'var(--md-sys-shape-corner-small)'
                                    }}>
                                        <input type="checkbox" id={`uda-select-${uda.id}`} checked={selectedUdaIds.includes(uda.id)} onChange={() => handleUdaSelection(uda.id)} />
                                        <label htmlFor={`uda-select-${uda.id}`} style={{
                                            cursor: 'pointer',
                                            flex: 1
                                        }}>{selectedUdaIds.includes(uda.id) && <span style={{
                                            fontFamily: 'Material Symbols Outlined',
                                            fontSize: 'var(--md-sys-typescale-body-medium-font-size)',
                                            color: 'var(--md-sys-color-primary)',
                                            marginRight: 'var(--md-sys-spacing-2)'
                                        }}>check</span>}{uda.title}</label>
                                    </div>
                                )) : <M3Typography variant="body-medium">Nessuna UDA trovata. Creane una nel Planner.</M3Typography>}
                            </div>
                        </div>
                        {/* Class Selection */}
                        <div style={{
                            backgroundColor: 'var(--md-sys-color-surface-container-low)',
                            borderRadius: 'var(--md-sys-shape-corner-medium)',
                            padding: 'var(--md-sys-spacing-4)'
                        }}>
                            <M3Typography variant="title-large" style={{marginBottom: 'var(--md-sys-spacing-3)'}}>2. Seleziona Classi</M3Typography>
                            {/* Centralized Selection Container */}
                            <div style={{
                                padding: 'var(--md-sys-spacing-2)',
                                border: '1px solid var(--md-sys-color-outline-variant)',
                                borderRadius: 'var(--md-sys-shape-corner-small)',
                                maxHeight: 'var(--md-sys-spacing-40)',
                                overflowY: 'auto'
                            }}>
                                {userClasses.map(c => (
                                    <div key={c} style={{
                                        display: 'flex',
                                        alignItems: 'center',
                                        gap: 'var(--md-sys-spacing-2)',
                                        padding: 'var(--md-sys-spacing-2)'
                                    }}>
                                        <input type="checkbox" id={`class-select-${c}`} checked={selectedClasses.includes(c)} onChange={() => handleClassSelection(c)} />
                                        <label htmlFor={`class-select-${c}`} style={{
                                            width: '100%',
                                            cursor: 'pointer',
                                            display: 'flex',
                                            alignItems: 'center'
                                        }}>{selectedClasses.includes(c) && <span style={{
                                            fontFamily: 'Material Symbols Outlined',
                                            fontSize: 'var(--md-sys-typescale-title-medium-font-size)',
                                            color: 'var(--md-sys-color-primary)',
                                            marginRight: 'var(--md-sys-spacing-2)'
                                        }}>check</span>}{c}</label>
                                    </div>
                                ))}
                            </div>
                        </div>
                        {/* KB Selection */}
                        <div style={{
                            backgroundColor: 'var(--md-sys-color-surface-container-low)',
                            borderRadius: 'var(--md-sys-shape-corner-medium)',
                            padding: 'var(--md-sys-spacing-4)'
                        }}>
                            <div style={{
                                display: 'flex',
                                justifyContent: 'space-between',
                                alignItems: 'center',
                                marginBottom: 'var(--md-sys-spacing-3)'
                            }}>
                                <M3Typography variant="title-large">3. Contesto KB</M3Typography>
                                <span style={{
                                    color: 'var(--md-sys-color-on-surface-variant)',
                                    fontSize: 'var(--md-sys-typescale-body-small-font-size)'
                                }}>{selectedKbIds.length} selezionati</span>
                            </div>
                            <div style={{
                                padding: 'var(--md-sys-spacing-2)',
                                border: '1px solid var(--md-sys-color-outline-variant)',
                                borderRadius: 'var(--md-sys-shape-corner-small)',
                                maxHeight: 'var(--md-sys-spacing-40)',
                                overflowY: 'auto'
                            }}>
                                {knowledgeBase.map(kb => (
                                    <div key={kb.id} style={{
                                        display: 'flex',
                                        alignItems: 'center',
                                        gap: 'var(--md-sys-spacing-2)',
                                        padding: 'var(--md-sys-spacing-2)'
                                    }}>
                                        <input type="checkbox" id={`kb-select-${kb.id}`} checked={selectedKbIds.includes(kb.id)} onChange={() => handleKbSelection(kb.id)} />
                                        <label htmlFor={`kb-select-${kb.id}`} style={{
                                            width: '100%',
                                            cursor: 'pointer',
                                            display: 'flex',
                                            alignItems: 'center',
                                            gap: 'var(--md-sys-spacing-2)'
                                        }} title={kb.fileName}>
                                            {selectedKbIds.includes(kb.id) && <span style={{
                                                fontFamily: 'Material Symbols Outlined',
                                                fontSize: 'var(--md-sys-typescale-title-medium-font-size)',
                                                color: 'var(--md-sys-color-primary)'
                                            }}>check</span>}
                                            <span style={{
                                                color: 'var(--md-sys-color-primary)',
                                                fontSize: 'var(--md-sys-typescale-body-medium-font-size)',
                                                fontFamily: 'Material Symbols Outlined'
                                            }}>{kb.isGenerated ? 'auto_awesome' : 'description'}</span>
                                            <span style={{
                                                overflow: 'hidden',
                                                textOverflow: 'ellipsis',
                                                whiteSpace: 'nowrap',
                                                flex: 1
                                            }}>{kb.fileName}</span>
                                        </label>
                                    </div>
                                ))}
                                {knowledgeBase.length === 0 && <M3Typography variant="body-medium" style={{
                                    color: 'var(--md-sys-color-on-surface-variant)'
                                }}>KB vuota.</M3Typography>}
                            </div>
                        </div>
                    </div>
                    <div style={{
                        marginTop: 'var(--md-sys-spacing-4)',
                        display: 'flex',
                        flexDirection: 'column',
                        gap: 'var(--md-sys-spacing-3)'
                    }}>
                        <button onClick={handleGenerateSequences} disabled={selectedUdaIds.length === 0 || selectedClasses.length === 0} style={{
                            width: '100%',
                            backgroundColor: selectedUdaIds.length === 0 || selectedClasses.length === 0 ? 'var(--md-sys-color-surface-container-highest)' : 'var(--md-sys-color-primary)',
                            color: selectedUdaIds.length === 0 || selectedClasses.length === 0 ? 'var(--md-sys-color-on-surface-variant)' : 'var(--md-sys-color-on-primary)',
                            border: 'none',
                            borderRadius: 'var(--md-sys-shape-corner-large)',
                            padding: 'var(--md-sys-spacing-4)',
                            fontSize: 'var(--md-sys-typescale-label-large-font-size)',
                            fontWeight: 'var(--md-sys-typescale-label-large-font-weight)',
                            cursor: selectedUdaIds.length === 0 || selectedClasses.length === 0 ? 'not-allowed' : 'pointer',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            gap: 'var(--md-sys-spacing-2)',
                            transition: 'all var(--md-sys-motion-duration-short-4) var(--md-sys-motion-easing-decelerated)-out'
                        }}>
                            <span style={{
                                fontFamily: 'Material Symbols Outlined',
                                fontSize: 'var(--md-sys-typescale-title-medium-font-size)'
                            }}>auto_awesome</span>
                            Genera Sequenze di Lezioni
                        </button>
                        {error && <M3Typography variant="body-medium" style={{
                            color: 'var(--md-sys-color-error)',
                            textAlign: 'center',
                            backgroundColor: 'var(--md-sys-color-error-container)',
                            padding: 'var(--md-sys-spacing-3)',
                            borderRadius: 'var(--md-sys-shape-corner-medium)',
                            border: '1px solid var(--md-sys-color-error)'
                        }}>{error}</M3Typography>}
                    </div>
                </div>
            </details>

            {/* Lessons Archive */}
            <div style={{
                backgroundColor: 'var(--md-sys-color-surface-container)',
                borderRadius: 'var(--md-sys-shape-corner-large)',
                padding: 'var(--md-sys-spacing-6)',
                marginTop: 'var(--md-sys-spacing-6)'
            }}>
                <div style={{
                    display: 'flex',
                    flexWrap: 'wrap',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    gap: 'var(--md-sys-spacing-4)',
                    marginBottom: 'var(--md-sys-spacing-6)',
                    borderBottom: '1px solid var(--md-sys-color-outline-variant)',
                    paddingBottom: 'var(--md-sys-spacing-4)'
                }}>
                    <M3Typography variant="headline-medium">Archivio Lezioni ({lessons.length})</M3Typography>

                    {/* Filtri */}
                    <div style={{
                        display: 'flex',
                        flexWrap: 'wrap',
                        gap: 'var(--md-sys-spacing-4)',
                        alignItems: 'center'
                    }}>
                        <div style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: 'var(--md-sys-spacing-3)'
                        }}>
                            <M3Typography variant="body-medium" style={{minWidth: 'fit-content'}}>Classe:</M3Typography>
                            <select value={filterClass} onChange={e => setFilterClass(e.target.value)} style={{
                                backgroundColor: 'var(--md-sys-color-surface-container-highest)',
                                color: 'var(--md-sys-color-on-surface)',
                                border: '1px solid var(--md-sys-color-outline)',
                                borderRadius: 'var(--md-sys-shape-corner-medium)',
                                padding: 'var(--md-sys-spacing-2) var(--md-sys-spacing-3)',
                                fontSize: 'var(--md-sys-typescale-body-medium-font-size)',
                                cursor: 'pointer'
                            }}>
                                <option value="">Tutte le classi</option>
                                {userClasses.map(c => <option key={c} value={c}>{c}</option>)}
                            </select>
                        </div>
                        <div style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: 'var(--md-sys-spacing-3)'
                        }}>
