                                <summary style={{
                                    padding: 'var(--md-sys-spacing-4)',
                                    backgroundColor: 'var(--md-sys-color-surface-container-highest)',
                                    borderRadius: 'var(--md-sys-shape-corner-medium) var(--md-sys-shape-corner-medium) 0 0',
                                    cursor: 'pointer',
                                    listStyle: 'none',
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'space-between'
                                }}>
