                        </M3Typography>
                        <M3Typography
                            variant="body-small"
                            style={{margin: 0,
                                color: 'color-mix(in srgb, var(--md-sys-color-on) 80%, transparent)', // MD3 EXCEPTION: Functional opacity for secondary text (no specific token available)
                                fontWeight: '400'}}
                        >
                            Classe {student.classe}
                        </M3Typography>
                    </div>
                </div>
                {/* Stats Row */}
                <div
                    style={{
                        display: 'flex',
                        justifyContent: 'space-between',
