                        </div>
                        <input 
                            type="checkbox"
                            checked={state.hasCapolavoro}
                            onChange={(e) => onUpdateState({ ...state, hasCapolavoro: e.target.checked })}
                             style={{ width: "var(--md-sys-spacing-5)", height: "var(--md-sys-spacing-5)" }}
