                <p
                  style={{
                    fontSize: bodyLargeFontSize,
                    fontWeight: bodyLargeFontWeight,
                    lineHeight: bodyLargeLineHeight,
                    color: onSurfaceVariant,
                    opacity: 0.8,
                    margin: `${spacing4} 0 0 0`,
                    display: '-webkit-box',
                    WebkitLineClamp: 2,
                    WebkitBoxOrient: 'vertical',
                    overflow: 'hidden'
                  }}
                >
                  {headline}
                </p>
              )}
            </div>

            {/* Close Button */}
            {!hideCloseButton && (
              <button
                onClick={onClose}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  padding: spacing4,
                  borderRadius: cornerLarge,
                  backgroundColor: closeButtonHovered ? surfaceContainerHigh : 'transparent',
                  border: 'none',
                  cursor: 'pointer',
                  transition: `background-color var(--md-sys-motion-duration-short) var(--md-sys-motion-easing-standard)`}}
                onMouseEnter={() => setCloseButtonHovered(true)}
                onMouseLeave={() => setCloseButtonHovered(false)}
                data-focus-priority="-1"
                aria-label="Chiudi"
              >
                <span
                  style={{fontFamily: 'Material Symbols Outlined',
                    fontSize: bodyLargeFontSize,
                    color: onSurfaceVariant}}
                >
                  close
                </span>
              </button>
            )}
          </div>
        )}

        {/* Content Section */}
        <div
          style={{flex: 1,
            padding: spacing6,
            overflowY: 'auto'}}
        >
          {children}
        </div>

        {/* Footer Section */}
        {(buttons || footerContent) && (
          <div
            style={{padding: spacing6,
              borderTop: `var(--md-sys-border-width-normal) solid ${outlineVariant}`,
              display: 'flex',
              justifyContent: 'flex-end',
              gap: 'var(--md-sys-spacing-3)'}}
          >
            {footerContent || buttons}
          </div>
        )}
      </div>
    </div>
  );
};

